// Approach: Move slow one node and fast two nodes at a time. Slow finishes at the middle (the second
//   middle when the length is even).
struct ListNode { int val; ListNode* next; };
ListNode* middleNode(ListNode* head) {
    // slow moves one node while fast moves two; slow reaches the middle.
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

