// Approach: Reverse the suffix first, then make its original first node point back to the current
//   node.
struct ListNode { int val; ListNode* next; };
ListNode* reverseRecursive(ListNode* head) {
    // The recursive call reverses the rest; reconnect this node on the way back.
    if (!head || !head->next) return head;
    ListNode* newHead = reverseRecursive(head->next);
    head->next->next = head;
    head->next = nullptr;
    return newHead;
}

