// Approach: Floyd's two pointers move at different speeds. They meet if and only if the list contains
//   a cycle.
struct ListNode { int val; ListNode* next; };
bool hasCycle(ListNode* head) {
    // If slow and fast ever meet, they are inside a cycle.
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

