// Approach: After the two pointers meet inside a cycle, move one to the head. Walking both one node
//   at a time finds the cycle entry.
struct ListNode { int val; ListNode* next; };
ListNode* detectCycle(ListNode* head) {
    // After the first meeting, move one pointer to head; equal steps find the entry.
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            slow = head;
            while (slow != fast) {
                slow = slow->next;
                fast = fast->next;
            }
            return slow;
        }
    }
    return nullptr;
}

