// Approach: Once Floyd's pointers meet, walk around the cycle until returning to that node and count
//   the links.
struct ListNode { int val; ListNode* next; };
int cycleLength(ListNode* head) {
    // Walk once around the cycle from the meeting point to count its nodes.
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            int count = 1;
            for (ListNode* p = slow->next; p != slow; p = p->next)
                ++count;
            return count;
        }
    }
    return 0;
}

s6-check-if-ll-is-palindrome-or-not.code:
// Approach: Find the first half's end, reverse the second half, compare values, then reverse it back
//   to restore the list.
struct ListNode { int val; ListNode* next; };
ListNode* reverseHalf(ListNode* head) {
    // This helper reverses a chain and returns its new head.
    ListNode* prev = nullptr;
    while (head) {
        ListNode* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}
bool isPalindrome(ListNode* head) {
    if (!head || !head->next) return true;
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    // Reversing lets both halves be compared from left to right.
    ListNode* second = reverseHalf(slow->next);
    ListNode* a = head;
    ListNode* b = second;
    bool equal = true;
    while (b) {
        if (a->val != b->val) { equal = false; break; }
        a = a->next;
        b = b->next;
    }
    // Restore the caller's list before returning the answer.
    slow->next = reverseHalf(second);
    return equal;
}

