// Approach: Keep fast n nodes ahead of slow, starting from a dummy node. When fast reaches the last
//   node, slow precedes the target.
struct ListNode { int val; ListNode* next; };
ListNode* removeNthFromEnd(ListNode* head, int n) {
    ListNode dummy{0, head};
    ListNode* fast = &dummy;
    for (int i = 0; i < n; ++i) {
        if (!fast->next) return head; // invalid n
        fast = fast->next;
    }
    ListNode* slow = &dummy;
    while (fast->next) {
        fast = fast->next;
        slow = slow->next;
    }
    ListNode* removed = slow->next;
    slow->next = removed->next;
    delete removed;
    return dummy.next;
}

