    // Use fast and slow pointers to locate the node before the middle.
    if (!head) return nullptr;
    if (!head->next) { delete head; return nullptr; }
    ListNode* prev = nullptr;
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        prev = slow;
        slow = slow->next;
        fast = fast->next->next;
    }
    prev->next = slow->next;
    delete slow;
    return head;
}

s6-sort-ll.code:
// Approach: Merge sort fits linked lists: split with slow/fast pointers, sort both halves, then merge
//   by relinking nodes.
struct ListNode { int val; ListNode* next; };
ListNode* mergeLists(ListNode* a, ListNode* b) {
    // Merge sort works well because linked lists split and merge through pointers.
    ListNode dummy{0, nullptr};
    ListNode* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}
ListNode* sortList(ListNode* head) {
    if (!head || !head->next) return head;
    ListNode* slow = head;
    ListNode* fast = head->next;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* right = slow->next;
    slow->next = nullptr;
    return mergeLists(sortList(head), sortList(right));
}

