// Approach: Walk pointers from both heads; when a pointer reaches the end, restart it at the other
//   head. They cover equal total distance and meet at the shared node.
struct ListNode { int val; ListNode* next; };
ListNode* intersectionNode(ListNode* a, ListNode* b) {
    ListNode* p = a;
    ListNode* q = b;
    while (p != q) {
        p = p ? p->next : b;
        q = q ? q->next : a;
    }
    return p; // shared node, or nullptr if no intersection
}

s6-add-1-to-a-number-represented-by-ll.code:
// Approach: For digits stored most-significant first, recurse to the tail with carry 1. Propagate the
//   carry backward and prepend a 1 if needed.
struct ListNode { int val; ListNode* next; };
int addCarry(ListNode* node) {
    // Carry starts at one and travels across the number's digits.
    if (!node) return 1;
    int sum = node->val + addCarry(node->next);
    node->val = sum % 10;
    return sum / 10;
}
ListNode* addOne(ListNode* head) {
    int carry = addCarry(head);
    if (carry) {
        ListNode* newHead = new ListNode{carry, head};
        return newHead;
    }
    return head;
}

s6-add-2-numbers-in-ll.code:
// Approach: For digits stored least-significant first, add corresponding digits and carry, building
//   the answer from the units place onward.
struct ListNode { int val; ListNode* next; };
ListNode* addTwoNumbers(ListNode* a, ListNode* b) {
    // Add matching digits and carry; continue while either list has nodes.
    ListNode dummy{0, nullptr};
    ListNode* tail = &dummy;
    int carry = 0;
    while (a || b || carry) {
        int sum = carry;
        if (a) { sum += a->val; a = a->next; }
        if (b) { sum += b->val; b = b->next; }
        tail->next = new ListNode{sum % 10, nullptr};
        tail = tail->next;
        carry = sum / 10;
    }
    return dummy.next;
}

