// Approach: For every matching node, reconnect its existing neighbors, update the head if needed, and
//   delete the detached node.
struct DNode { int val; DNode* prev; DNode* next; };
DNode* deleteAll(DNode* head, int key) {
    // When deleting a node, reconnect both its previous and next neighbors.
    DNode* cur = head;
    while (cur) {
        DNode* next = cur->next;
        if (cur->val == key) {
            if (cur->prev) cur->prev->next = cur->next;
            else head = cur->next;
            if (cur->next) cur->next->prev = cur->prev;
            delete cur;
        }
        cur = next;
    }
    return head;
}

s6-find-pairs-with-given-sum-in-dll.code:
// Approach: The doubly linked list must be sorted. Start at both ends and move inward according to
//   the sum, just like two pointers on a sorted array.
#include <utility>
#include <vector>
using namespace std;
struct DNode { int val; DNode* prev; DNode* next; };
vector<pair<int, int>> pairsWithSum(DNode* head, int target) {
    // A sorted doubly linked list supports two pointers from opposite ends.
    vector<pair<int, int>> answer;
    if (!head) return answer;
    DNode* left = head;
    DNode* right = head;
    while (right->next) right = right->next;
    while (left != right && left->prev != right) {
        long long sum = (long long)left->val + right->val;
        if (sum == target) {
            answer.push_back({left->val, right->val});
            left = left->next;
            right = right->prev;
        } else if (sum < target) left = left->next;
        else right = right->prev;
    }
    return answer;
}

s6-remove-duplicates-from-sorted-dll.code:
// Approach: Because equal values are adjacent in a sorted list, compare each node with its successor
//   and unlink duplicates in place.
struct DNode { int val; DNode* prev; DNode* next; };
DNode* removeDuplicates(DNode* head) {
    // Equal neighbors are duplicates because the list is sorted.
    for (DNode* cur = head; cur && cur->next; ) {
        if (cur->val != cur->next->val) {
            cur = cur->next;
        } else {
            DNode* duplicate = cur->next;
            cur->next = duplicate->next;
            if (cur->next) cur->next->prev = cur;
            delete duplicate;
        }
    }
    return head;
}

s6-reverse-ll-in-group-of-given-size-k.code:
// Approach: Reverse exactly k nodes at a time. First check that a full group exists; leave a shorter
//   final group unchanged.
struct ListNode { int val; ListNode* next; };
ListNode* reverseKGroup(ListNode* head, int k) {
    // Reverse one group of k nodes, then join it to the next group.
    if (k <= 1) return head;
    ListNode dummy{0, head};
    ListNode* before = &dummy;
    while (true) {
        ListNode* end = before;
        for (int i = 0; i < k && end; ++i) end = end->next;
        if (!end) break; // leave an incomplete final group unchanged
        ListNode* after = end->next;
        ListNode* prev = after;
        ListNode* cur = before->next;
        while (cur != after) {
            ListNode* next = cur->next;
            cur->next = prev;
            prev = cur;
            cur = next;
        }
        // The old first node is now the tail of this reversed group.
        ListNode* oldStart = before->next;
        before->next = end;
        before = oldStart;
    }
    return dummy.next;
}

