s6-inserting-a-node-in-linkedlist.code:
// Approach: To insert at a 0-based position, find the preceding node and link the new node between it
//   and its former successor. Position 0 updates the head.
struct ListNode { int val; ListNode* next; };
ListNode* insertAt(ListNode* head, int position, int value) {
    if (position < 0) return head;
    if (position == 0) return new ListNode{value, head};
    ListNode* prev = head;
    for (int i = 1; i < position && prev; ++i)
        prev = prev->next;
    if (!prev) return head; // position exceeds length
    prev->next = new ListNode{value, prev->next};
    return head;
}

