// Approach: To delete at a 0-based position, find its predecessor, bypass the target, and release it.
//   A dummy head also handles position 0.
struct ListNode { int val; ListNode* next; };
ListNode* eraseAt(ListNode* head, int position) {
    // Keep the previous node so its next link can skip the deleted node.
    if (position < 0) return head;
    ListNode dummy{0, head};
    ListNode* prev = &dummy;
    for (int i = 0; i < position && prev; ++i)
        prev = prev->next;
    if (prev && prev->next) {
        ListNode* target = prev->next;
        prev->next = target->next;
        delete target;
    }
    return dummy.next;
}

