// Approach: Insert at a 0-based position by connecting the new node to its two neighbors and updating
//   both neighbors' pointers.
struct DNode { int val; DNode* prev; DNode* next; };
DNode* insertAt(DNode* head, int position, int value) {
    // Insertion updates both directions of the surrounding links.
    if (position < 0) return head;
    if (position == 0) {
        DNode* node = new DNode{value, nullptr, head};
        if (head) head->prev = node;
        return node;
    }
    DNode* prev = head;
    for (int i = 1; i < position && prev; ++i)
        prev = prev->next;
    if (!prev) return head;
    DNode* node = new DNode{value, prev, prev->next};
    if (prev->next) prev->next->prev = node;
    prev->next = node;
    return head;
}

