// Approach: Partition nodes into three chains for 0, 1 and 2, then join those chains. This relinks
//   nodes without changing their values.
struct ListNode { int val; ListNode* next; };
ListNode* sort012(ListNode* head) {
    ListNode zero{0, nullptr}, one{0, nullptr}, two{0, nullptr};
    ListNode* tail[3] = {&zero, &one, &two};
    while (head) {
        ListNode* next = head->next;
        head->next = nullptr;
        tail[head->val]->next = head; // values are 0, 1 or 2
        tail[head->val] = head;
        head = next;
    }
    tail[0]->next = one.next ? one.next : two.next;
    tail[1]->next = two.next;
    return zero.next ? zero.next : (one.next ? one.next : two.next);
}

