// Approach: Reduce k modulo the length. Connect tail to head to make a ring, then cut after length-k
//   nodes for a right rotation.
struct ListNode { int val; ListNode* next; };
ListNode* rotateRight(ListNode* head, int k) {
    // Connect the tail to head temporarily, then break at the new tail.
    if (!head || !head->next || k == 0) return head;
    int length = 1;
    ListNode* tail = head;
    while (tail->next) { tail = tail->next; ++length; }
    k %= length;
    if (k == 0) return head;
    tail->next = head;
    ListNode* newTail = head;
    for (int i = 1; i < length - k; ++i)
        newTail = newTail->next;
    ListNode* newHead = newTail->next;
    newTail->next = nullptr;
    return newHead;
}

s6-flattening-of-ll.code:
// Approach: Each top-level node starts a sorted bottom chain. Merge all chains with a min-heap,
//   joining the result through bottom pointers.
#include <queue>
#include <vector>
using namespace std;
struct FlatNode { int val; FlatNode* next; FlatNode* bottom; };
FlatNode* flatten(FlatNode* head) {
    // Merge sorted child chains while preserving their sorted order.
    struct Greater {
        bool operator()(const FlatNode* a, const FlatNode* b) const {
            return a->val > b->val;
        }
    };
    priority_queue<FlatNode*, vector<FlatNode*>, Greater> heap;
    for (FlatNode* p = head; p; p = p->next) heap.push(p);
    FlatNode dummy{0, nullptr, nullptr};
    FlatNode* tail = &dummy;
    // Take the smallest available node, then offer its next bottom node.
    while (!heap.empty()) {
        FlatNode* node = heap.top();
        heap.pop();
        if (node->bottom) heap.push(node->bottom);
        node->next = nullptr;
        tail->bottom = node;
        tail = node;
    }
    tail->bottom = nullptr;
    return dummy.bottom;
}

s6-clone-a-linked-list-with-random-and-n.code:
// Approach: Interleave each clone after its original, assign clone random pointers via
//   original->random->next, then separate the two lists.
struct RandomNode { int val; RandomNode* next; RandomNode* random; };
RandomNode* cloneList(RandomNode* head) {
    // Every original node needs a distinct copy and matching random link.
    if (!head) return nullptr;
    for (RandomNode* cur = head; cur; ) {
        RandomNode* next = cur->next;
        cur->next = new RandomNode{cur->val, next, nullptr};
        cur = next;
    }
    // An original's random target is followed immediately by its clone.
    for (RandomNode* cur = head; cur; cur = cur->next->next)
        cur->next->random = cur->random ? cur->random->next : nullptr;
    RandomNode* copyHead = head->next;
    // Separate the interleaved chain and restore every original next link.
    for (RandomNode* cur = head; cur; ) {
        RandomNode* copy = cur->next;
        cur->next = copy->next;
        copy->next = cur->next ? cur->next->next : nullptr;
        cur = cur->next;
    }
    return copyHead;
}
